    :IMAKUNI_CARD => {:label => "ImakuniCard", :type => "TYPE_TRAINER", :gfx => "imakuni", :name => "Imakuni?", :rarity => "PROMOSTAR", :sets => ["PROMOTIONAL", "PRO"], :effect => "ImakuniEffectCommands", :desc => "Your Active Pokémon is now Confused.\nImakuni wants you to play him as a\nBasic Pokémon, but you can't.\nA mysterious creature not listed in\nthe Pokédex. He asks kids around the\nworld,”Who is cuter-Pikachu or me?”"},
    :POKEMON_TRADER => {:label => "PokemonTraderCard", :type => "TYPE_TRAINER", :gfx => "pokemontrader", :name => "Pokémon Trader", :rarity => "STAR", :sets => ["EVOLUTION"], :effect => "PokemonTraderEffectCommands", :desc => "Trade 1 of the Basic Pokémon or\nEvolution cards in your hand for 1\nof the Basic Pokémon or Evolution\ncards from your deck. Show both\ncards to your opponent.\nShuffle your deck afterward."},
    :POKEMON_BREEDER => {:label => "PokemonBreederCard", :type => "TYPE_TRAINER", :gfx => "pokemonbreeder", :name => "Pokémon Breeder", :rarity => "STAR", :sets => ["EVOLUTION"], :effect => "PokemonBreederEffectCommands", :desc => "Put a Stage 2 Evolution card from\nyour hand on the matching Basic\nPokémon. You can only play this card\nwhen you would be allowed to evolve\nthat Pokémon anyway."},
    :CLEFAIRY_DOLL => {:label => "ClefairyDollCard", :type => "TYPE_TRAINER", :gfx => "clefairydoll", :name => "Clefairy Doll", :rarity => "STAR", :sets => ["EVOLUTION"], :effect => "ClefairyDollEffectCommands", :desc => "Play Clefairy Doll as if it were a\nBasic Pokémon. While in play,\nClefairy Doll counts as a Pokémon\n(instead of a Trainer card).\nClefairy Doll has no attacks, can't\nretreat, and can't be Asleep,\nConfused, Paralyzed, or Poisoned.\nIf Clefairy Doll is Knocked Out, it\ndoesn't count as a Knocked Out\nPokémon. At any time during your\nturn before your attack, you may\ndiscard Clefairy Doll.\n(Use GameBoy Pokémon Power menu\noption to do this.)"},
    :MYSTERIOUS_FOSSIL => {:label => "MysteriousFossilCard", :type => "TYPE_TRAINER", :gfx => "mysteriousfossil", :name => "Mysterious Fossil", :rarity => "CIRCLE", :sets => ["MYSTERY", "FOSSIL"], :effect => "MysteriousFossilEffectCommands", :desc => "Play Mysterious Fossil as if it were\na Basic Pokémon. While in play,\nMysterious Fossil counts as a\nPokémon (instead of a Trainer card).\nMysterious Fossil has no attacks,\ncan't retreat, and can't be Asleep,\nConfused, Paralyzed, or Poisoned.\nIf Mysterious Fossil is Knocked Out,\nit doesn't count as a Knocked Out\nPokémon. (Discard it anyway.) At any\ntime during your turn before your\nattack, you may discard Mysterious\nFossil from play. (Use GameBoy Poké-\nmon Power menu option to do this.)"},
    :ENERGY_RETRIEVAL => {:label => "EnergyRetrievalCard", :type => "TYPE_TRAINER", :gfx => "energyretrieval", :name => "Energy Retrieval", :rarity => "DIAMOND", :sets => ["EVOLUTION"], :effect => "EnergyRetrievalEffectCommands", :desc => "Trade 1 of the other cards in your\nhand for up to 2 basic Energy cards\nfrom your discard pile."},
    :SUPER_ENERGY_RETRIEVAL => {:label => "SuperEnergyRetrievalCard", :type => "TYPE_TRAINER", :gfx => "superenergyretrieval", :name => "Super Energy Retrieval", :rarity => "PROMOSTAR", :sets => ["PROMOTIONAL", "PRO"], :effect => "SuperEnergyRetrievalEffectCommands", :desc => "Trade 2 of the other cards in your\nhand for up to 4 basic Energy cards\nfrom your discard pile."},
    :ENERGY_SEARCH => {:label => "EnergySearchCard", :type => "TYPE_TRAINER", :gfx => "energysearch", :name => "Energy Search", :rarity => "CIRCLE", :sets => ["EVOLUTION", "FOSSIL"], :effect => "EnergySearchEffectCommands", :desc => "Search your deck for a basic Energy\ncard and put it into your hand.\nShuffle your deck afterward."},
    :ENERGY_REMOVAL => {:label => "EnergyRemovalCard", :type => "TYPE_TRAINER", :gfx => "energyremoval", :name => "Energy Removal", :rarity => "CIRCLE", :sets => ["MYSTERY"], :effect => "EnergyRemovalEffectCommands", :desc => "Choose 1 Energy card attached to 1\nof your opponent's Pokémon and\ndiscard it."},
    :SUPER_ENERGY_REMOVAL => {:label => "SuperEnergyRemovalCard", :type => "TYPE_TRAINER", :gfx => "superenergyremoval", :name => "Super Energy Removal", :rarity => "STAR", :sets => ["LABORATORY"], :effect => "SuperEnergyRemovalEffectCommands", :desc => "Discard 1 Energy card attached to 1\nof your own Pokémon in order to\nchoose 1 of your opponent's Pokémon\nand up to 2 Energy cards attached\nto it. Discard those Energy cards."},
    :SWITCH => {:label => "SwitchCard", :type => "TYPE_TRAINER", :gfx => "switch", :name => "Switch", :rarity => "CIRCLE", :sets => ["COLOSSEUM"], :effect => "SwitchEffectCommands", :desc => "Switch 1 of your Benched Pokémon\nwith your Active Pokémon."},
    :POKEMON_CENTER => {:label => "PokemonCenterCard", :type => "TYPE_TRAINER", :gfx => "pokemoncenter", :name => "Pokémon Center", :rarity => "DIAMOND", :sets => ["MYSTERY"], :effect => "PokemonCenterEffectCommands", :desc => "Remove all damage counters from all\nof your own Pokémon with damage\ncounters on them, then discard all\nEnergy cards attached to those\nPokémon."},
    :POKE_BALL => {:label => "PokeBallCard", :type => "TYPE_TRAINER", :gfx => "pokeball", :name => "Poké Ball", :rarity => "CIRCLE", :sets => ["COLOSSEUM", "JUNGLE"], :effect => "PokeBallEffectCommands", :desc => "Flip a coin. If heads, you may\nsearch your deck for any Basic\nPokémon or Evolution card. Show that\ncard to your opponent, then put it\ninto your hand. Shuffle your deck\nafterward."},
    :SCOOP_UP => {:label => "ScoopUpCard", :type => "TYPE_TRAINER", :gfx => "scoopup", :name => "Scoop Up", :rarity => "STAR", :sets => ["COLOSSEUM"], :effect => "ScoopUpEffectCommands", :desc => "Choose 1 of your Pokémon in play\nand return its Basic Pokémon card to\nyour hand. (Discard all cards\nattached to that card.)"},
    :COMPUTER_SEARCH => {:label => "ComputerSearchCard", :type => "TYPE_TRAINER", :gfx => "computersearch", :name => "Computer Search", :rarity => "STAR", :sets => ["COLOSSEUM"], :effect => "ComputerSearchEffectCommands", :desc => "Discard 2 of the other cards from\nyour hand in order to search your\ndeck for any card and put it into\nyour hand. Shuffle your deck\nafterward."},
    :POKEDEX => {:label => "PokedexCard", :type => "TYPE_TRAINER", :gfx => "pokedex", :name => "Pokédex", :rarity => "DIAMOND", :sets => ["LABORATORY"], :effect => "PokedexEffectCommands", :desc => "Look at up to 5 cards from the top\nof your deck and rearrange them as\nyou like."},
    :PLUSPOWER => {:label => "PlusPowerCard", :type => "TYPE_TRAINER", :gfx => "pluspower", :name => "PlusPower", :rarity => "DIAMOND", :sets => ["COLOSSEUM"], :effect => "PlusPowerEffectCommands", :desc => "Attach PlusPower to your Active\nPokémon. At the end of your turn,\ndiscard PlusPower. If this Pokémon's\nattack does damage to any Active\nPokémon (after applying Weakness and\nResistance), the attack does 10 more\ndamage to that Active Pokémon."},
    :DEFENDER => {:label => "DefenderCard", :type => "TYPE_TRAINER", :gfx => "defender", :name => "Defender", :rarity => "DIAMOND", :sets => ["COLOSSEUM"], :effect => "DefenderEffectCommands", :desc => "Attach Defender to 1 of your\nPokémon. At the end of your\nopponent's next turn, discard\nDefender. Damage done to that\nPokémon by attacks is reduced by 20\n(after applying Weakness and\nResistance)."},
    :ITEM_FINDER => {:label => "ItemFinderCard", :type => "TYPE_TRAINER", :gfx => "itemfinder", :name => "Item Finder", :rarity => "STAR", :sets => ["COLOSSEUM"], :effect => "ItemFinderEffectCommands", :desc => "Discard 2 of the other cards from\nyour hand in order to put a Trainer\ncard from your discard pile into\nyour hand."},
    :GUST_OF_WIND => {:label => "GustOfWindCard", :type => "TYPE_TRAINER", :gfx => "gustofwind", :name => "Gust of Wind", :rarity => "CIRCLE", :sets => ["EVOLUTION"], :effect => "GustOfWindEffectCommands", :desc => "Choose 1 of your opponent's Benched\nPokémon and switch it with his or\nher Active Pokémon."},
    :DEVOLUTION_SPRAY => {:label => "DevolutionSprayCard", :type => "TYPE_TRAINER", :gfx => "devolutionspray", :name => "Devolution Spray", :rarity => "STAR", :sets => ["LABORATORY"], :effect => "DevolutionSprayEffectCommands", :desc => "Choose 1 of your own Pokémon in play\nand a Stage of Evolution. Discard\nall Evolution cards of that Stage or\nhigher attached to that Pokémon.\nThat Pokémon is no longer Asleep,\nConfused, Paralyzed, Poisoned, or\nanything else that might be the\nresult of an attack (just as if you\nhad evolved it)."},
    :POTION => {:label => "PotionCard", :type => "TYPE_TRAINER", :gfx => "potion", :name => "Potion", :rarity => "CIRCLE", :sets => ["COLOSSEUM"], :effect => "PotionEffectCommands", :desc => "Remove 2 damage counters from 1 of\nyour Pokémon. If that Pokémon has\nfewer damage counters than that,\nremove all of them."},
    :SUPER_POTION => {:label => "SuperPotionCard", :type => "TYPE_TRAINER", :gfx => "superpotion", :name => "Super Potion", :rarity => "DIAMOND", :sets => ["EVOLUTION"], :effect => "SuperPotionEffectCommands", :desc => "Discard 1 Energy card attached to 1\nof your own Pokémon in order to\nremove 4 damage counters from that\nPokémon. If the Pokémon has fewer\ndamage counters than that, remove\nall of them."},
    :FULL_HEAL => {:label => "FullHealCard", :type => "TYPE_TRAINER", :gfx => "fullheal", :name => "Full Heal", :rarity => "DIAMOND", :sets => ["COLOSSEUM"], :effect => "FullHealEffectCommands", :desc => "Your Active Pokémon is no longer\nAsleep, Confused, Paralyzed, or\nPoisoned."},
    :REVIVE => {:label => "ReviveCard", :type => "TYPE_TRAINER", :gfx => "revive", :name => "Revive", :rarity => "DIAMOND", :sets => ["COLOSSEUM"], :effect => "ReviveEffectCommands", :desc => "Put 1 Basic Pokémon card from your\ndiscard pile onto your Bench.\nPut damage counters on that Pokémon\nequal to half its HP (rounded down\nto the nearest 10). (You can't play\nRevive if your Bench is full.)"},
    :MAINTENANCE => {:label => "MaintenanceCard", :type => "TYPE_TRAINER", :gfx => "maintenance", :name => "Maintenance", :rarity => "DIAMOND", :sets => ["LABORATORY"], :effect => "MaintenanceEffectCommands", :desc => "Shuffle 2 of the other cards from\nyour hand into your deck in order\nto draw a card."},
    :POKEMON_FLUTE => {:label => "PokemonFluteCard", :type => "TYPE_TRAINER", :gfx => "pokemonflute", :name => "Pokémon Flute", :rarity => "DIAMOND", :sets => ["EVOLUTION"], :effect => "PokemonFluteEffectCommands", :desc => "Choose 1 Basic Pokémon card from\nyour opponent's discard pile and put\nit onto his or her Bench. (You can't\nplay Pokémon Flute if your\nopponent's Bench is full.)"},
    :GAMBLER => {:label => "GamblerCard", :type => "TYPE_TRAINER", :gfx => "gambler", :name => "Gambler", :rarity => "CIRCLE", :sets => ["LABORATORY", "FOSSIL"], :effect => "GamblerEffectCommands", :desc => "Shuffle your hand into your deck.\nFlip a coin. If heads, draw 8 cards.\nIf tails, draw 1 card."},
    :RECYCLE => {:label => "RecycleCard", :type => "TYPE_TRAINER", :gfx => "recycle", :name => "Recycle", :rarity => "CIRCLE", :sets => ["LABORATORY", "FOSSIL"], :effect => "RecycleEffectCommands", :desc => "Flip a coin. If heads, put a card\nin your discard pile on top of your\ndeck."},
  }

